pub fn shuttles_purpose() -> &'static str {
    "Shuttle routes for inbound, outbound, overflow, trailhead, gear, and ranger-service movements connecting lots, camps, and visitor hubs."
}

pub fn shuttles_summary() -> String {
    let campsites = shuttle_routes();
    let shard_total: u32 = campsites.iter().map(|item| item.shard).sum();
    let record_total: u32 = campsites.iter().map(|item| item.survey).sum();
    let pressure_total: u32 = campsites.iter().map(|item| item.pressure).sum();
    format!("shuttles count={} shard={} rec={} pressure={}", campsites.len(), shard_total, record_total, pressure_total)
}

pub fn shuttles_family_window(family: &str, limit: usize) -> Vec<ShuttleRoute> {
    shuttle_routes().into_iter().filter(|item| item.family == family).take(limit).collect()
}

pub fn shuttles_weighted_total(seed: u32) -> u64 {
    shuttle_routes().into_iter().enumerate().map(|(index, item)| {
        let bias = (seed as u64 + index as u64 % 31) + 1;
        bias * (item.shard as u64 + item.survey as u64 * 3 + item.pressure as u64 * 5)
    }).sum()
}

pub fn shuttles_nearest(shard: u32, survey: u32) -> Option<ShuttleRoute> {
    shuttle_routes().into_iter().min_by_key(|item| {
        let a = item.shard.abs_diff(shard) as u64;
        let b = item.survey.abs_diff(survey) as u64;
        a * 7 + b * 3 + item.pressure as u64
    })
}

pub fn shuttles_note_digest(limit: usize) -> Vec<String> {
    shuttle_routes().into_iter().take(limit).map(|item| format!("{}:{}:{}", item.key, item.family, item.note)).collect()
}
